package com.studentforum;

import java.util.*;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api")
class CollectionController {
    private final KnowledgeService k;
    CollectionController(KnowledgeService k){this.k=k;}
    @GetMapping("/{kind:collections|columns}")
    Map<String,Object> list(Authentication auth,@PathVariable String kind,@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="false") boolean mine,@RequestParam(defaultValue="false") boolean featured,@RequestParam(defaultValue="false") boolean favorite,@RequestParam(defaultValue="false") boolean following,@RequestParam(defaultValue="1") int page){k.check(!(mine||favorite||following) || k.user(auth)>0,"请先登录");k.check(q.length()<=100,"关键词过长");String sql="SELECT c.*,u.username FROM "+kind+" c JOIN users u ON u.id=c.owner_id WHERE "+(mine?"c.owner_id=?":"c.status='active' AND ?>=0")+" AND (?='' OR LOCATE(?,c.title)>0 OR LOCATE(?,c.description)>0)";if(kind.equals("collections") && featured)sql+=" AND c.is_featured=TRUE";if(kind.equals("collections") && favorite)sql+=" AND EXISTS(SELECT 1 FROM collection_favorites f WHERE f.collection_id=c.id AND f.user_id="+k.user(auth)+")";if(kind.equals("collections") && following)sql+=" AND EXISTS(SELECT 1 FROM collection_follows f WHERE f.collection_id=c.id AND f.user_id="+k.user(auth)+")";sql+=" ORDER BY "+(kind.equals("collections")?"c.is_featured DESC,":"")+"c.id DESC LIMIT 21 OFFSET ?";return k.page(k.db.queryForList(sql,k.user(auth),q,q,q,k.offset(page)));}
    @PostMapping("/{kind:collections|columns}") @Transactional
    Map<String,Object> create(Authentication auth,@PathVariable String kind,@RequestBody Map<String,Object> input){k.forum.writable(auth);long id=k.insert("INSERT INTO "+kind+"(owner_id,title,description,cover_url) VALUES(?,?,?,?)",k.user(auth),k.text(input,"title",2,120),k.text(input,"description",0,500),k.forum.image(input.get("coverUrl")));return Map.of("id",id);}
    @PatchMapping("/{kind:collections|columns}/{id}") @Transactional
    void edit(Authentication auth,@PathVariable String kind,@PathVariable long id,@RequestBody Map<String,Object> input){var r=kind.equals("collections")?k.collection(auth,id):k.column(auth,id);k.owner(auth,r,"owner_id");k.check("active".equals(r.get("status")),"已停用的内容不能编辑");k.db.update("UPDATE "+kind+" SET title=?,description=?,cover_url=? WHERE id=?",k.text(input,"title",2,120),k.text(input,"description",0,500),k.forum.image(input.get("coverUrl")),id);}
    @GetMapping("/collections/{id}")
    Map<String,Object> detail(Authentication auth,@PathVariable long id){var r=k.collection(auth,id);List<Map<String,Object>> visible=new ArrayList<>();for(var item:k.db.queryForList("SELECT * FROM collection_items WHERE collection_id=? ORDER BY sort_order,id",id)){try{var target=k.item(auth,String.valueOf(item.get("item_type")),k.n(item,"item_id"));var copy=new LinkedHashMap<>(item);copy.put("title",target.get("title"));visible.add(copy);}catch(ResponseStatusException e){if(e.getStatusCode().value()!=404 && e.getStatusCode().value()!=400)throw e;}}
        r.put("items",visible);r.put("item_count",visible.size());r.put("followed",k.row("SELECT 1 FROM collection_follows WHERE collection_id=? AND user_id=?",id,k.user(auth))!=null);r.put("favorited",k.row("SELECT 1 FROM collection_favorites WHERE collection_id=? AND user_id=?",id,k.user(auth))!=null);return r;}
    @PostMapping("/collections/{id}/items") @Transactional
    void add(Authentication auth,@PathVariable long id,@RequestBody Map<String,Object> input){var collection=k.collection(auth,id);k.owner(auth,collection,"owner_id");k.check("active".equals(collection.get("status")),"合集已停用");k.required("SELECT id FROM collections WHERE id=? FOR UPDATE",id);String type=k.choice(input,"itemType","post","post","resource","note");long target=k.number(input,"itemId",0);var item=k.item(auth,type,target);long sort=k.number(input,"sortOrder",0);k.check(sort>=0 && sort<=10000,"排序值无效");k.db.update("INSERT INTO collection_items(collection_id,item_type,item_id,title,sort_order) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE sort_order=VALUES(sort_order)",id,type,target,item.get("title"),sort);recount(id);}
    private void recount(long id){k.db.update("UPDATE collections SET item_count=(SELECT COUNT(*) FROM collection_items WHERE collection_id=?) WHERE id=?",id,id);}
    @PatchMapping("/collections/{id}/items/{itemId}")
    void reorder(Authentication auth,@PathVariable long id,@PathVariable long itemId,@RequestBody Map<String,Object> input){k.owner(auth,k.collection(auth,id),"owner_id");long sort=k.number(input,"sortOrder",0);k.check(sort>=0 && sort<=10000,"排序值无效");k.required("SELECT id FROM collection_items WHERE id=? AND collection_id=?",itemId,id);k.db.update("UPDATE collection_items SET sort_order=? WHERE id=? AND collection_id=?",sort,itemId,id);}
    @DeleteMapping("/collections/{id}/items/{itemId}") @Transactional
    void remove(Authentication auth,@PathVariable long id,@PathVariable long itemId){k.owner(auth,k.collection(auth,id),"owner_id");k.required("SELECT id FROM collections WHERE id=? FOR UPDATE",id);k.db.update("DELETE FROM collection_items WHERE id=? AND collection_id=?",itemId,id);recount(id);}
    @PostMapping("/collections/{id}/{action:follow|favorite}") @Transactional
    void toggle(Authentication auth,@PathVariable long id,@PathVariable String action,@RequestBody Map<String,Object> input){k.forum.writable(auth);var r=k.collection(auth,id);k.check("active".equals(r.get("status")),"合集已停用");k.required("SELECT id FROM collections WHERE id=? FOR UPDATE",id);String table=action.equals("follow")?"collection_follows":"collection_favorites";if(Boolean.TRUE.equals(input.get("active")))k.db.update("INSERT IGNORE INTO "+table+"(collection_id,user_id) VALUES(?,?)",id,k.user(auth));else k.db.update("DELETE FROM "+table+" WHERE collection_id=? AND user_id=?",id,k.user(auth));k.db.update("UPDATE collections SET follower_count=(SELECT COUNT(*) FROM collection_follows WHERE collection_id=?) WHERE id=?",id,id);}
    @GetMapping("/columns/{id}")
    Map<String,Object> column(Authentication auth,@PathVariable long id){var r=k.column(auth,id);r.put("episodes",k.db.queryForList("SELECT * FROM column_episodes WHERE column_id=? AND (status='published' OR ?=?) ORDER BY episode_no",id,k.n(r,"owner_id"),k.user(auth)));return r;}
    @PostMapping("/columns/{id}/episodes") @Transactional
    Map<String,Object> episode(Authentication auth,@PathVariable long id,@RequestBody Map<String,Object> input){var c=k.column(auth,id);k.owner(auth,c,"owner_id");k.check("active".equals(c.get("status")),"专栏已停用");k.required("SELECT id FROM columns WHERE id=? FOR UPDATE",id);long no=k.number(input,"episodeNo",1);k.check(no>=1 && no<=10000,"期数无效");k.check(k.row("SELECT id FROM column_episodes WHERE column_id=? AND episode_no=?",id,no)==null,"此期数已存在");String status=k.choice(input,"status","published","draft","published");long noteId=k.number(input,"noteId",0);String title,content;if(noteId>0){var note=k.note(auth,noteId);k.owner(auth,note,"user_id");k.check(!status.equals("published") || "published".equals(note.get("status")),"发布连载需使用已发布笔记");title=String.valueOf(note.get("title"));content=String.valueOf(note.get("content"));}else{title=k.text(input,"title",2,160);content=k.text(input,"content",1,30000);}
        long episode=k.insert("INSERT INTO column_episodes(column_id,note_id,title,content,episode_no,status) VALUES(?,?,?,?,?,?)",id,noteId>0?noteId:null,title,content,no,status);return Map.of("id",episode);}
    @PatchMapping("/columns/{id}/episodes/{episodeId}")
    void editEpisode(Authentication auth,@PathVariable long id,@PathVariable long episodeId,@RequestBody Map<String,Object> input){k.owner(auth,k.column(auth,id),"owner_id");k.required("SELECT id FROM column_episodes WHERE id=? AND column_id=?",episodeId,id);k.db.update("UPDATE column_episodes SET title=?,content=?,status=? WHERE id=? AND column_id=?",k.text(input,"title",2,160),k.text(input,"content",1,30000),k.choice(input,"status","published","draft","published"),episodeId,id);}
    @GetMapping("/admin/collections")
    Map<String,Object> admin(Authentication auth,@RequestParam(defaultValue="1") int page){k.forum.admin(auth);return k.page(k.db.queryForList("SELECT c.*,u.username FROM collections c JOIN users u ON u.id=c.owner_id ORDER BY c.id DESC LIMIT 21 OFFSET ?",k.offset(page)));}
    @PatchMapping("/admin/collections/{id}") @Transactional
    void recommend(Authentication auth,@PathVariable long id,@RequestBody Map<String,Object> input){k.forum.admin(auth);k.required("SELECT id FROM collections WHERE id=?",id);String status=k.choice(input,"status","active","active","disabled");boolean featured=Boolean.TRUE.equals(input.get("featured")) && status.equals("active");k.db.update("UPDATE collections SET is_featured=?,status=? WHERE id=?",featured,status,id);k.audit(auth,"collection_recommend","collection",id,status+"/"+featured);}
}
